{
  "verdicts": [
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Supported by PRI-FTPMC-001 which lists married couples aged ≤40, never owned, and no BTO/SBF booking as criteria."
    },
    {
      "claim_id": "c3",
      "outcome": "insufficient_evidence",
      "rationale": "HH-CIT-001 requires at least one SC or SPR household member, but does not state both applicants must be SC."
    },
    {
      "claim_id": "c4",
      "outcome": "supported",
      "rationale": "HH-SUBSIDY-001 defines first‑timer families as those with no prior subsidy, matching the claim."
    },
    {
      "claim_id": "c6",
      "outcome": "insufficient_evidence",
      "rationale": "DOC-STATUS-001 only describes employment status options, not required document list."
    },
    {
      "claim_id": "c7",
      "outcome": "insufficient_evidence",
      "rationale": "DOC-STATUS-001 does not cover portal login or selection steps."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Fact HH-NONRES-002 states the Singapore Citizen applicant must be at least 35 years old for a new flat with a non-resident spouse."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Fact APP-CHANGE-002 requires household details in the flat application to match the approved HFE letter and any change needs a new HFE letter."
    },
    {
      "claim_id": "c3",
      "outcome": "supported",
      "rationale": "Fact HH-PROP-001 specifies no applicant or occupier may own/hold interest in private residential property and a sold property imposes a 30‑month wait before HFE application."
    },
    {
      "claim_id": "c4",
      "outcome": "insufficient_evidence",
      "rationale": "Fact HFE-APPLY-001 only mentions online application and Singpass login; it does not address submitting the flat application before the HFE letter expires."
    },
    {
      "claim_id": "c5",
      "outcome": "supported",
      "rationale": "Fact HFE-RENEW-001 advises applying for a fresh HFE letter if the current one will expire within 30 days and more time is needed."
    },
    {
      "claim_id": "c6",
      "outcome": "insufficient_evidence",
      "rationale": "Fact HH-CIT-001 does not mention prior HDB flat or subsidy status; the claim adds a condition not covered by the cited fact."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Supported by HFE-STEPS-001 which states the two steps must be done no more than 30 calendar days apart."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Supported by HFE-TIME-001 which states HDB takes up to one month to process a complete HFE letter application."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "HH-COUPLE-001 explicitly states an engaged couple counts as a core family nucleus and can apply together."
    },
    {
      "claim_id": "c2",
      "outcome": "insufficient_evidence",
      "rationale": "PRI-FTPMC-001 does not confirm that engaged couples qualify, marking it as unconfirmed, so the claim's inclusion of engaged couples lacks support."
    },
    {
      "claim_id": "c3",
      "outcome": "supported",
      "rationale": "CTX-HFE-001 states the HFE letter confirms eligibility and indicates CPF grant and HDB loan amounts."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "HH-CIT-001 states both must be Singapore Citizens, which matches the claim."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "HH-AGE-001 requires applicants to be 21 or older, which both spouses are."
    },
    {
      "claim_id": "c3",
      "outcome": "insufficient_evidence",
      "rationale": "HH-SUBSIDY-001 confirms first‑timer status but does not state it is a prerequisite for the couples scheme."
    },
    {
      "claim_id": "c4",
      "outcome": "supported",
      "rationale": "PRI-FTPMC-001 and HH-COUPLE-002 together define married childless couples aged 40 or below as FT(PMC) first‑timer families."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Fact HH-PROP-001 explicitly states the ownership restriction."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Fact HH-PROP-001 explicitly states the 30‑month waiting period after sale."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "HH-AGE-002 states an engaged partner under 21 may appear only as a core occupier, not as an applicant."
    },
    {
      "claim_id": "c3",
      "outcome": "insufficient_evidence",
      "rationale": "HH-CIT-001 requires the applicant to be a Singapore Citizen but does not require both partners to be Citizens."
    },
    {
      "claim_id": "c4",
      "outcome": "supported",
      "rationale": "HFE-APPLY-001 specifies the HFE letter is applied for online via the HDB Flat Portal with Singpass and is free."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "HH-AGE-001 states the applicant must be 21 or older under the couples scheme."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "HH-CIT-001 specifies the applicant must be a Singapore Citizen and household must include another SC or SPR."
    },
    {
      "claim_id": "c3",
      "outcome": "supported",
      "rationale": "HFE-APPLY-001 indicates applicants log in with Singpass and apply for the HFE letter online."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Fact HFE-STEPS-001 states the two steps must be done no more than 30 calendar days apart, matching the claim."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Fact HFE-STEPS-001 specifies that if the steps fall in different calendar months, employment and income details must be updated, which the claim restates."
    },
    {
      "claim_id": "c3",
      "outcome": "supported",
      "rationale": "Fact HFE-STEPS-001 requires updating details when steps are in different months; the applicant's dates span October to November, so the claim correctly applies this requirement."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Fact HFE-VALID-001 states the HFE letter stays valid for 9 months from issuance."
    },
    {
      "claim_id": "c3",
      "outcome": "insufficient_evidence",
      "rationale": "Fact HFE-APPLY-001 only describes the online free application process, not that the letter is required before flat application."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Fact HH-MARRY-001 states the marriage must be registered within 3 months after flat purchase and HDB may ask to see the certificate, matching the claim."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Supported by PRI-FTPMC-001 which defines eligibility for married couples ≤40 and notes engaged couples are unconfirmed."
    },
    {
      "claim_id": "c2",
      "outcome": "contradicted",
      "rationale": "HH-CIT-001 requires only one applicant to be a Singapore Citizen, not both."
    },
    {
      "claim_id": "c3",
      "outcome": "supported",
      "rationale": "PRI-FTPMC-001 states applicants must never have owned/sold residential property and must not have booked a BTO/SBF in the past 5 years."
    },
    {
      "claim_id": "c8",
      "outcome": "insufficient_evidence",
      "rationale": "PRI-FTPMC-001 mentions child or expected child criteria but does not specify needing a birth certificate."
    },
    {
      "claim_id": "c9",
      "outcome": "insufficient_evidence",
      "rationale": "HFE-RENEW-001 covers renewal within 30 days but does not state the letter is typically valid for 6 months."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Supported by PRI-FTPMC-001 which states FT(PMC) families must never have owned or sold a residential property, including an HDB flat."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Supported by PRI-FTPMC-002 which states buyers do not apply for the FT(PMC) category and HDB determines eligibility after submission."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "HH-AGE-002 specifies the restriction only for partners under 21, implying that partners over 21 may appear as applicants."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c2",
      "outcome": "insufficient_evidence",
      "rationale": "Fact CTX-HFE-001 only states the HFE letter shows grant amounts, not that applicants should apply."
    },
    {
      "claim_id": "c3",
      "outcome": "insufficient_evidence",
      "rationale": "Fact CTX-WORK-001 requires employment for the HFE letter but does not mention required documents."
    }
  ]
}

{
  "verdicts": [
    {
      "claim_id": "c1",
      "outcome": "supported",
      "rationale": "Supported by HH-FLAT-001 which states couples under the fiancé/fiancée scheme may buy a flat up to 5 rooms."
    },
    {
      "claim_id": "c2",
      "outcome": "supported",
      "rationale": "Supported by PRI-FTPMC-003 which specifies FT(PMC) families have three ballot chances in each BTO/SBF exercise."
    },
    {
      "claim_id": "c4",
      "outcome": "supported",
      "rationale": "Supported by APP-BALLOT-001 which says the computer ballot sets the queue order after the application period closes."
    }
  ]
}
